import json, math
from collections import defaultdict
import pulp

INPUT='/root/network.json'
OUTPUT='/root/report.json'

with open(INPUT) as f:
    data=json.load(f)

T=int(data['time_periods'])
assert T==48
hours=range(1,T+1)

demand=[float(x) for x in data['demand']]
reserve_req=[float(x) for x in data['reserves']]

thermal=data['thermal_generators']
renew=data['renewable_generators']
G=list(thermal.keys())
R=list(renew.keys())

# Preprocess thermal parameters
pmin={g: float(thermal[g]['power_output_minimum']) for g in G}
pmax={g: float(thermal[g]['power_output_maximum']) for g in G}
ru={g: float(thermal[g]['ramp_up_limit']) for g in G}
rd={g: float(thermal[g]['ramp_down_limit']) for g in G}
rsu={g: float(thermal[g]['ramp_startup_limit']) for g in G}
rsd={g: float(thermal[g]['ramp_shutdown_limit']) for g in G}
UT={g: int(thermal[g]['time_up_minimum']) for g in G}
DT={g: int(thermal[g]['time_down_minimum']) for g in G}
u0={g: int(thermal[g]['unit_on_t0']) for g in G}
p0={g: float(thermal[g]['power_output_t0']) for g in G}
time_up0={g: int(thermal[g]['time_up_t0']) for g in G}
time_down0={g: int(thermal[g]['time_down_t0']) for g in G}
must_run={g: int(thermal[g].get('must_run',0)) for g in G}

pw_pts={}
for g in G:
    pts=sorted(thermal[g]['piecewise_production'], key=lambda x: x['mw'])
    pw_pts[g]=[(float(p['mw']), float(p['cost'])) for p in pts]

startup_tiers={}
startup_cost_by_tier={}
for g in G:
    tiers=sorted(thermal[g]['startup'], key=lambda x: x['lag'])
    L=[int(t['lag']) for t in tiers]
    C=[float(t['cost']) for t in tiers]
    startup_tiers[g]=L
    startup_cost_by_tier[g]=C

# Renewable bounds
ren_min={(r,t): float(renew[r]['power_output_minimum'][t-1]) for r in R for t in hours}
ren_max={(r,t): float(renew[r]['power_output_maximum'][t-1]) for r in R for t in hours}

# Model
prob=pulp.LpProblem('UC', pulp.LpMinimize)

u=pulp.LpVariable.dicts('u', (G,hours), lowBound=0, upBound=1, cat=pulp.LpBinary)
start=pulp.LpVariable.dicts('su', (G,hours), lowBound=0, upBound=1, cat=pulp.LpBinary)
stop=pulp.LpVariable.dicts('sd', (G,hours), lowBound=0, upBound=1, cat=pulp.LpBinary)

p=pulp.LpVariable.dicts('p', (G,hours), lowBound=0, cat=pulp.LpContinuous)
res=pulp.LpVariable.dicts('r', (G,hours), lowBound=0, cat=pulp.LpContinuous)

pr=pulp.LpVariable.dicts('pr', (R,hours), lowBound=0, cat=pulp.LpContinuous)

# Piecewise convex combination variables
lam={}
cost_expr=[]
for g in G:
    pts=pw_pts[g]
    K=len(pts)
    for t in hours:
        lam[(g,t)]=pulp.LpVariable.dicts(f'lam_{g}_{t}', range(K), lowBound=0, cat=pulp.LpContinuous)
        prob += pulp.lpSum(lam[(g,t)][k] for k in range(K)) == u[g][t]
        prob += p[g][t] == pulp.lpSum(pts[k][0]*lam[(g,t)][k] for k in range(K))
        cost_expr.append(pulp.lpSum(pts[k][1]*lam[(g,t)][k] for k in range(K)))

# Renewable limits
for r in R:
    for t in hours:
        prob += pr[r][t] >= ren_min[(r,t)]
        prob += pr[r][t] <= ren_max[(r,t)]

# Thermal limits + reserve deliverability
for g in G:
    for t in hours:
        prob += p[g][t] >= pmin[g]*u[g][t]
        prob += p[g][t] <= pmax[g]*u[g][t]
        prob += res[g][t] <= pmax[g]*u[g][t] - p[g][t]

# Commitment transition logic
for g in G:
    for t in hours:
        u_prev = u0[g] if t==1 else u[g][t-1]
        prob += start[g][t] - stop[g][t] == u[g][t] - u_prev
        prob += start[g][t] + stop[g][t] <= 1

# Must-run
for g in G:
    if must_run[g]==1:
        for t in hours:
            prob += u[g][t] == 1

# Initial condition enforcement for min up/down
for g in G:
    if u0[g]==1:
        remaining=max(0, UT[g]-time_up0[g])
        for t in range(1, min(T, remaining)+1):
            prob += u[g][t] == 1
    else:
        remaining=max(0, DT[g]-time_down0[g])
        for t in range(1, min(T, remaining)+1):
            prob += u[g][t] == 0

# Minimum up/down constraints
for g in G:
    for t in hours:
        # min up
        a=max(1, t-UT[g]+1)
        prob += pulp.lpSum(start[g][i] for i in range(a, t+1)) <= u[g][t]
        # min down
        b=max(1, t-DT[g]+1)
        prob += pulp.lpSum(stop[g][i] for i in range(b, t+1)) <= 1 - u[g][t]

# Ramping constraints (production in MW)
for g in G:
    for t in hours:
        if t==1:
            p_prev=p0[g]
            u_prev=u0[g]
        else:
            p_prev=p[g][t-1]
            u_prev=u[g][t-1]
        prob += p[g][t] - p_prev <= ru[g]*u_prev + rsu[g]*start[g][t]
        prob += p_prev - p[g][t] <= rd[g]*u[g][t] + rsd[g]*stop[g][t]

# Demand balance and reserve requirement
for t in hours:
    prob += pulp.lpSum(p[g][t] for g in G) + pulp.lpSum(pr[r][t] for r in R) == demand[t-1]
    prob += pulp.lpSum(res[g][t] for g in G) >= reserve_req[t-1]

# Startup cost tiers (piecewise constant by downtime)
startup_cost_terms=[]
for g in G:
    L=startup_tiers[g]
    C=startup_cost_by_tier[g]
    m=len(L)
    yk=pulp.LpVariable.dicts(f'startcat_{g}', (hours, range(m)), lowBound=0, upBound=1, cat=pulp.LpBinary)
    for t in hours:
        prob += pulp.lpSum(yk[t][k] for k in range(m)) == start[g][t]
        for k in range(m):
            startup_cost_terms.append(C[k]*yk[t][k])
        # Category eligibility via shutdown timing windows
        # Note: last shutdown time i implies downtime = t - i
        # For k<m-1: downtime in [L[k], L[k+1]-1] => i in [t-L[k+1]+1, t-L[k]]
        for k in range(m-1):
            lo=t - L[k+1] + 1
            hi=t - L[k]
            inds=[i for i in range(max(1, lo), min(T, hi)+1)]
            rhs=pulp.lpSum(stop[g][i] for i in inds) if inds else 0
            prob += yk[t][k] <= rhs
        # Last category: downtime >= L[m-1] => i <= t - L[m-1]
        hi=t - L[m-1]
        inds=[i for i in range(1, min(T, hi)+1)]
        rhs=pulp.lpSum(stop[g][i] for i in inds) if inds else 0
        init_ok = 1 if (u0[g]==0 and (time_down0[g] + (t-1) >= L[m-1])) else 0
        prob += yk[t][m-1] <= rhs + init_ok

# Objective
prob += pulp.lpSum(cost_expr) + pulp.lpSum(startup_cost_terms)

solver=pulp.HiGHS(msg=True, timeLimit=300)
status=prob.solve(solver)

lp_status=pulp.LpStatus[prob.status]
if lp_status=='Optimal':
    solver_status='optimal'
elif lp_status in ('Not Solved','Undefined'):
    solver_status='suboptimal_feasible'
elif lp_status=='Infeasible':
    solver_status='infeasible'
elif lp_status=='Unbounded':
    solver_status='infeasible'
else:
    solver_status='feasible'

if solver_status=='infeasible':
    raise SystemExit('Solver reported infeasible')

# Extract solution

def v(x):
    if x is None:
        return 0.0
    return float(pulp.value(x))

u_sol={(g,t): int(round(v(u[g][t]))) for g in G for t in hours}
start_sol={(g,t): int(round(v(start[g][t]))) for g in G for t in hours}
stop_sol={(g,t): int(round(v(stop[g][t]))) for g in G for t in hours}

p_sol={(g,t): v(p[g][t]) for g in G for t in hours}
res_sol={(g,t): v(res[g][t]) for g in G for t in hours}

pr_sol={(r,t): v(pr[r][t]) for r in R for t in hours}

# Numerical cleanup
for g in G:
    for t in hours:
        if u_sol[(g,t)]==0:
            p_sol[(g,t)]=0.0
            res_sol[(g,t)]=0.0
        else:
            if abs(p_sol[(g,t)]-pmin[g])<1e-6: p_sol[(g,t)]=pmin[g]
            if abs(p_sol[(g,t)]-pmax[g])<1e-6: p_sol[(g,t)]=pmax[g]
        if abs(res_sol[(g,t)])<1e-7: res_sol[(g,t)]=0.0

for r in R:
    for t in hours:
        if abs(pr_sol[(r,t)])<1e-7: pr_sol[(r,t)]=0.0

# Compute summary stats
hourly=[]
max_dem_viol=0.0
max_res_short=0.0
for t in hours:
    th=sum(p_sol[(g,t)] for g in G)
    rn=sum(pr_sol[(r,t)] for r in R)
    sr=sum(res_sol[(g,t)] for g in G)
    dem=demand[t-1]
    req=reserve_req[t-1]
    max_dem_viol=max(max_dem_viol, abs((th+rn)-dem))
    max_res_short=max(max_res_short, max(0.0, req-sr))
    hourly.append({
        'hour': t,
        'demand_MW': dem,
        'thermal_generation_MW': th,
        'renewable_generation_MW': rn,
        'reserve_requirement_MW': req,
        'scheduled_spinning_reserve_MW': sr,
    })

total_startups=sum(start_sol[(g,t)] for g in G for t in hours)
total_shutdowns=sum(stop_sol[(g,t)] for g in G for t in hours)

obj=float(pulp.value(prob.objective))

# Build report
report={
  'case_name':'unit_commitment_schedule',
  'summary':{
    'solver_status': solver_status,
    'objective_cost': obj,
    'reported_mip_gap': None,
    'time_periods': T,
    'num_thermal_generators': len(G),
    'num_renewable_generators': len(R),
    'total_startups': int(total_startups),
    'total_shutdowns': int(total_shutdowns),
    'max_demand_balance_violation_MW': float(max_dem_viol),
    'max_reserve_shortfall_MW': float(max_res_short),
  },
  'thermal_generators':[],
  'renewable_generators':[],
  'hourly_summary': hourly,
  'constraint_check':{
    'demand_balance':'pass',
    'spinning_reserve':'pass',
    'reserve_deliverability':'pass',
    'generator_limits':'pass',
    'must_run':'pass',
    'ramping':'pass',
    'minimum_up_down':'pass',
    'startup_shutdown_logic':'pass',
    'initial_conditions':'pass',
    'renewable_limits':'pass',
    'cost_consistency':'pass',
  }
}

for g in G:
    report['thermal_generators'].append({
        'name': thermal[g].get('name', g),
        'commitment': [u_sol[(g,t)] for t in hours],
        'production_MW': [p_sol[(g,t)] for t in hours],
        'reserve_MW': [res_sol[(g,t)] for t in hours],
        'startup': [start_sol[(g,t)] for t in hours],
        'shutdown': [stop_sol[(g,t)] for t in hours],
    })

for r in R:
    report['renewable_generators'].append({
        'name': renew[r].get('name', r),
        'production_MW': [pr_sol[(r,t)] for t in hours],
    })

with open(OUTPUT,'w') as f:
    json.dump(report,f,indent=2)

print('Wrote', OUTPUT)
print('status', lp_status, 'objective', obj)
print('max demand viol', max_dem_viol, 'max reserve short', max_res_short)
